graph_mermaid:
---
config:
  flowchart:
    curve: linear
---
graph TD;
	__start__([<p>__start__</p>]):::first
	supervisor(supervisor)
	sentinel(sentinel)
	investigator(investigator)
	liaison(liaison)
	sourcing(sourcing)
	approval(approval)
	procurement(procurement)
	treasurer(treasurer)
	verifier(verifier)
	__end__([<p>__end__</p>]):::last
	__start__ --> supervisor;
	approval --> supervisor;
	investigator --> supervisor;
	liaison --> supervisor;
	procurement --> supervisor;
	sentinel --> supervisor;
	sourcing --> supervisor;
	supervisor -.-> __end__;
	supervisor -.-> approval;
	supervisor -.-> investigator;
	supervisor -.-> liaison;
	supervisor -.-> procurement;
	supervisor -.-> sentinel;
	supervisor -.-> sourcing;
	supervisor -.-> treasurer;
	supervisor -.-> verifier;
	treasurer --> supervisor;
	verifier --> supervisor;
	classDef default fill:#f2f0ff,line-height:1.2
	classDef first fill-opacity:0
	classDef last fill:#bfb6fc
